<section class="page-hero"><div class="container"><span class="eyebrow">01 / 04</span><h1><?= __('apply_page_title') ?></h1><p><?= __('cta_desc') ?></p></div></section>
<section class="section section-soft"><div class="container form-shell"><form id="applyForm" class="application-form"><div class="form-progress"><span class="active">01</span><span>02</span><span>03</span><span>04</span></div><div class="form-step active"><h2>Tell us about you</h2><div class="form-grid"><label>Full name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Nationality<input name="nationality" required></label><label>Passport number<input name="passport"></label></div><button type="button" class="btn btn-primary next-step">Continue ↗</button></div><div class="form-step"><h2>Choose a service</h2><div class="choice-grid"><label><input type="radio" name="service" value="Vietnam E-Visa" checked><span>Vietnam E-Visa</span></label><label><input type="radio" name="service" value="Business Visa"><span>Business Visa</span></label><label><input type="radio" name="service" value="Work Permit"><span>Work Permit</span></label><label><input type="radio" name="service" value="Temporary Residence Card"><span>Temporary Residence Card</span></label></div><div class="form-actions"><button type="button" class="btn btn-secondary prev-step">← Back</button><button type="button" class="btn btn-primary next-step">Continue ↗</button></div></div><div class="form-step"><h2>Travel information</h2><div class="form-grid"><label>Expected entry date<input type="date" name="entry_date"></label><label>Entry point<input name="entry_point" placeholder="e.g. Tan Son Nhat"></label><label class="full"><textarea name="message" rows="5" placeholder="Tell us anything we should know"></textarea></label></div><div class="form-actions"><button type="button" class="btn btn-secondary prev-step">← Back</button><button type="button" class="btn btn-primary next-step">Review ↗</button></div></div><div class="form-step"><h2>Review your request</h2><div class="review-box" id="applicationReview"></div><p class="form-note">Frontend only: this form is ready for the backend developer to connect to API/database.</p><div class="form-actions"><button type="button" class="btn btn-secondary prev-step">← Back</button><button type="submit" class="btn btn-primary">Submit request ↗</button></div></div><div class="form-success" id="formSuccess" hidden><span class="success-icon">✓</span><h2>Request prepared</h2><p>The frontend demo is complete. Connect this submit action to your backend/API.</p></div></form></div></section>
